import re
from decimal import Decimal

MAX_CENTS = 100_000_000  # 1000000.00

# Plain decimal: optional sign, then digits with an optional fraction.
# No whitespace, no exponent, no underscores.
_PLAIN_DECIMAL = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)")


def amount_to_cents(value):
    """Validate an amount and return it as an exact integer number of cents.

    Uses only exact integer and Decimal-constructor arithmetic, so the global
    decimal context is never consulted or modified.
    """
    if isinstance(value, bool):
        raise ValueError("boolean is not a valid amount")
    if isinstance(value, float):
        raise ValueError("float is not a valid amount; pass Decimal, int or str")
    if isinstance(value, int):
        d = Decimal(value)
    elif isinstance(value, Decimal):
        d = value
    elif isinstance(value, str):
        if not _PLAIN_DECIMAL.fullmatch(value):
            raise ValueError(f"not a plain decimal string: {value!r}")
        d = Decimal(value)
    else:
        raise ValueError(f"unsupported amount type: {type(value).__name__}")

    if not d.is_finite():
        raise ValueError("non-finite amount")
    if d.is_zero():
        raise ValueError("amount must be greater than zero")
    if d.is_signed():
        raise ValueError("amount must be positive")
    if d.adjusted() > 6:  # magnitude >= 10**7, always over the maximum
        raise ValueError("amount exceeds 1000000.00")

    _, digits, exp = d.as_tuple()
    coef = int("".join(map(str, digits)))
    # Drop trailing zeros below the cent position; they carry no value.
    while exp < -2 and coef % 10 == 0:
        coef //= 10
        exp += 1
    if exp < -2:
        raise ValueError("amount is not exactly representable in cents")

    cents = coef * 10 ** (exp + 2)
    if cents > MAX_CENTS:
        raise ValueError("amount exceeds 1000000.00")
    return cents


def cents_to_amount(cents):
    """Return an exact Decimal with exponent -2 for an integer cent count."""
    return Decimal(f"{cents // 100}.{cents % 100:02d}")


def parse_amount(value):
    return cents_to_amount(amount_to_cents(value))


def format_amount(value):
    return format(value, ".2f")
