from .money import amount_to_cents, cents_to_amount, format_amount, MAX_CENTS


def make_invoice(amounts):
    # list() copies the input; the caller's sequence is never mutated.
    items = list(amounts)
    total = 0
    for item in items:
        total += amount_to_cents(item)
    if total > MAX_CENTS:
        raise ValueError("invoice total exceeds 1000000.00")
    return {"total": format_amount(cents_to_amount(total)), "count": len(items)}
